#define maxlod 63. 
//for a max lod of n you will get a (2^n)^2 square example a max lod of 4 would result in a 16x16 pattern.
#define quad vec4(0,1,2,3).xzwy
//swizzle the components of this vector to change the resultiiing pattern xzwy is used for the originlal bayer pattern.


void cdi/*constuct dither iteration*/(inout float col,in vec2 pos, inout float strength,inout float squaresize){


    float sqsx2=2.*squaresize;

    pos=mod(pos,sqsx2);

    bool sx=pos.x<squaresize;
    bool sy=pos.y<squaresize;

    if( sx && sy ){col+=quad.x*strength;}else{
    if(!sx && sy ){col+=quad.y*strength;}else{
    if( sx &&!sy ){col+=quad.z*strength;}else{
    if(!sx &&!sy ){col+=quad.w*strength;}}}}

    strength*=0.25;
    squaresize =sqsx2;


}

void dither(inout vec4 col,in vec2 pos){

    float strength=exp2(2.*(maxlod-1.));
    float squaresize=1.;
    float dith =0.;

    for(int i=1;i<=int(maxlod);i++){
        cdi(dith,pos,strength,squaresize);
    }
         dith/=exp2(maxlod*2.);

    if(col.x<=dith){col.x=0.;}else{col.x=1.;}
    if(col.y<=dith){col.y=0.;}else{col.y=1.;}
    if(col.z<=dith){col.z=0.;}else{col.z=1.;}
    if(col.w<=dith){col.w=0.;}else{col.w=1.;}

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    fragColor = vec4(sin(iTime)/1.95+0.5,sin(iTime*2.)/1.95+0.5,sin(iTime*3.)/1.95+0.5,0);
    dither(fragColor,fragCoord);
}
